WITH o AS ( SELECT order_id FROM orders WHERE NOT is_deleted AND status NOT IN ('cancelled', 'canceled', 'payment_failed') AND CAST(order_at AS DATE) BETWEEN DATE '2025-10-01' AND DATE '2025-10-31'), cap AS (SELECT SUM(p.amount_bdt) AS amt FROM payments p JOIN o ON o.order_id = p.order_id WHERE p.status = 'captured'), ref AS (SELECT SUM(r.amount_bdt) AS amt FROM refunds r JOIN o ON o.order_id = r.order_id) SELECT COALESCE((SELECT amt FROM cap), 0) - COALESCE((SELECT amt FROM ref), 0) AS value
